<?php
require __DIR__.'/../config/app.php';require_role('admin');
$activityId=(int)($_GET['id']??0);$activity=null;$rows=[];$error='';$search=trim((string)($_GET['q']??''));
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf_check();$registrationId=(int)($_POST['registration_id']??0);
 try{$q=db()->prepare('DELETE FROM activity_registrations WHERE id=? AND activity_id=?');$q->execute([$registrationId,$activityId]);flash($q->rowCount()?'Registration removed.':'Registration not found.');}catch(Throwable $t){flash('Could not remove the registration.','error');}
 go('admin/activity-registrations.php?id='.$activityId);
}
try{$q=db()->prepare('SELECT id,title,activity_date,venue FROM cultural_activities WHERE id=?');$q->execute([$activityId]);$activity=$q->fetch();if($activity){$q=db()->prepare('SELECT r.id,r.created_at,u.name,u.email FROM activity_registrations r JOIN users u ON u.id=r.user_id WHERE r.activity_id=? AND (?=\'\' OR u.name LIKE ? OR u.email LIKE ?) ORDER BY r.created_at DESC');$term='%'.$search.'%';$q->execute([$activityId,$search,$term,$term]);$rows=$q->fetchAll();}}catch(Throwable $t){$error='Could not load registrations.';}
if(!$activity){http_response_code(404);exit('Activity not found.');}if(($_GET['export']??'')==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="activity-registrations-'.$activityId.'.csv"');$out=fopen('php://output','w');fputcsv($out,['Student','Email','Registered']);foreach($rows as $r)fputcsv($out,[$r['name'],$r['email'],$r['created_at']]);fclose($out);exit;}
$perPage=25;$totalRecords=count($rows);$totalPages=(int)ceil($totalRecords/$perPage);$currentPage=max(1,min($totalPages?:1,(int)($_GET['page']??1)));$rows=array_slice($rows,($currentPage-1)*$perPage,$perPage);$pageTitle='Activity Registrations';$bodyClass='dashboard-page admin-page';$activePage='cultural';$adminSection='cultural';require __DIR__.'/../includes/header.php';
?><div class="dash-layout admin-layout"><?php require __DIR__.'/../includes/sidebar.php';?><main class="content-page admin-content admin-events-page"><header class="admin-page-heading"><div><span class="admin-eyebrow">CAMPUS CULTURE</span><h1><?=e($activity['title'])?> Registrations</h1><p><?=date('d M Y',strtotime($activity['activity_date']))?> · <?=e($activity['venue'])?></p></div><a class="btn outline" href="<?=url('admin/cultural.php')?>">Back to Activities</a></header><?php require __DIR__.'/section-nav.php';?><?php if($error):?><div class="inline-error"><?=e($error)?></div><?php endif;?><section class="admin-work-card"><div class="admin-card-heading"><span class="admin-heading-icon"><?=eventhub_icon('people')?></span><div><h2>Registered students <span class="admin-count"><?=count($rows)?></span></h2><p>Students who joined this activity.</p></div></div><form method="get" class="admin-report-filters"><input type="hidden" name="id" value="<?=$activityId?>"><input name="q" value="<?=e($search)?>" placeholder="Search name or email"><button class="btn primary">Search</button><a class="btn outline" href="<?=url('admin/activity-registrations.php?'.http_build_query(['id'=>$activityId,'q'=>$search,'export'=>'csv']))?>">Export CSV</a></form><?php if($rows):?><div class="table-wrap admin-table-wrap"><table><thead><tr><th>Student</th><th>Email</th><th>Registered</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong></td><td><?=e($r['email'])?></td><td><?=date('d M Y, g:i A',strtotime($r['created_at']))?></td><td><form method="post" onsubmit="return confirm('Remove this student registration?')"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="registration_id" value="<?=$r['id']?>"><button class="text-button danger-text" type="submit">Remove</button></form></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty">No students have registered for this activity yet.</div><?php endif;?></section><?php require __DIR__.'/../includes/admin-pagination.php';?></main></div><?php require __DIR__.'/../includes/footer.php';
